// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.FrontierStateArena;
import org.junit.jupiter.api.Test;

class LmdbFrontierExistsProbeMemoTest {

	@Test
	void completeDomainAnswersPartiallyBoundKeysWithoutEvaluatorFallback() {
		try (FrontierStateArena arena = new FrontierStateArena(1L << 20);
				LmdbFrontierExistsProbeMemo memo = LmdbFrontierExistsProbeMemo.createIfCapacity(
						arena, new String[] { "left", "right" })) {
			assertNotNull(memo);
			assertTrue(memo.completeMatchDomain(new FrontierPrimitiveCorrelationRelation(
					2, new long[] { 11L, 21L, 11L, 22L, 12L, 23L }, new double[] { 1.0d, 1.0d, 1.0d })));

			assertEquals(LmdbFrontierExistsProbeMemo.MATCH, memo.get(new long[] { 11L, 0L }));
			assertEquals(LmdbFrontierExistsProbeMemo.NO_MATCH, memo.get(new long[] { 13L, 0L }));
			assertEquals(LmdbFrontierExistsProbeMemo.MATCH, memo.get(new long[] { 0L, 23L }));
			assertEquals(LmdbFrontierExistsProbeMemo.NO_MATCH, memo.get(new long[] { 0L, 24L }));
			assertEquals(LmdbFrontierExistsProbeMemo.MATCH, memo.get(new long[] { 0L, 0L }));
			assertEquals(LmdbFrontierExistsProbeMemo.MATCH, memo.get(new long[] { 11L, 21L }));
			assertEquals(LmdbFrontierExistsProbeMemo.NO_MATCH, memo.get(new long[] { 11L, 23L }));
		}
	}

	@Test
	void completeEmptyAndUncorrelatedDomainsRemainExact() {
		try (FrontierStateArena arena = new FrontierStateArena(1L << 20);
				LmdbFrontierExistsProbeMemo empty = LmdbFrontierExistsProbeMemo.createIfCapacity(
						arena, new String[] { "left", "right" });
				LmdbFrontierExistsProbeMemo uncorrelated = LmdbFrontierExistsProbeMemo.createIfCapacity(
						arena, new String[0])) {
			assertNotNull(empty);
			assertTrue(empty.completeMatchDomain(
					new FrontierPrimitiveCorrelationRelation(2, new long[0], new double[0])));
			assertEquals(LmdbFrontierExistsProbeMemo.NO_MATCH, empty.get(new long[] { 0L, 0L }));
			assertEquals(LmdbFrontierExistsProbeMemo.NO_MATCH, empty.get(new long[] { 11L, 0L }));

			assertNotNull(uncorrelated);
			assertTrue(uncorrelated.completeMatchDomain(
					new FrontierPrimitiveCorrelationRelation(0, new long[0], new double[] { 1.0d })));
			assertEquals(LmdbFrontierExistsProbeMemo.MATCH, uncorrelated.get(new long[0]));
		}
	}
}
